def remise_magasin(nb_casiers):
    """Renvoie le taux de remise d'un magasin, en pour cent : 0, 2 ou 5."""
    if nb_casiers >= 10:
        return 5
    elif nb_casiers >= 5:
        return 2
    else:
        return 0

